// ── EDIT THE PROMPT HERE ──────────────────────────────────────────
// Same task as the Gemini workflow, but produces an OpenAI chat body for
// a LOCAL model. entities/edges are already credential-sanitised backend-side.
const body = $json.body || $json;
const entities = (body.entities || []).map(e => ({ id: e.id, type: e.entity_type, label: e.label, data: e.data }));
const edges = (body.edges || []).map(e => ({ from: e.from_entity, to: e.to_entity, relation: e.relation_type }));

const SYSTEM = `You are an OSINT analyst assistant for a law-enforcement case tool.
Given a case graph (entities + edges), do THREE things, grounded ONLY in the provided data:
1) identity_clusters: which entities most likely belong to the SAME real person/actor, with rationale and 0-1 confidence;
2) suggested_edges: plausible NEW relationships between EXISTING entities (never invent entities), each with relation, rationale, confidence;
3) narrative + next_steps.
Never fabricate. Respond ONLY as JSON:
{"identity_clusters":[{"entity_ids":[],"rationale":"","confidence":0}],"suggested_edges":[{"from_id":"","to_id":"","relation":"","rationale":"","confidence":0}],"narrative":"","next_steps":[]}`;

const user = `ENTITIES:\n` + JSON.stringify(entities, null, 1) + `\n\nEDGES:\n` + JSON.stringify(edges, null, 1);

const openai_body = {
  model: body.local_model || "llama3.1",
  messages: [ { role: "system", content: SYSTEM }, { role: "user", content: user } ],
  temperature: 0.2,
  response_format: { type: "json_object" }
};

return [{ json: {
  case_id: body.case_id || null,
  base_url: (body.local_base_url || "").replace(/\/$/, ""),
  openai_body
} }];

// OpenAI-compatible: choices[0].message.content = the JSON string.
const r = $json;
let text = '';
try { text = r.choices[0].message.content; } catch (e) { text = ''; }
let parsed = {};
try { parsed = JSON.parse(text); } catch (e) { parsed = { error: 'model did not return valid JSON', raw: text }; }
return [{ json: parsed }];
